#!/usr/bin/env node
// rynth/vt/tools/gen_pet_essences.cjs — builds rynth/vt/data/pet_essences.json
// (PLAN W1-9 SUP, §2.4 M21) from ACE's PetDevice.PetDeviceToPetMapping
// (ACE/ACE.Server/WorldObjects/PetDevice.cs, vanilla, read-only): essence
// (PetDevice) wcid -> { petWcid, damageType }.
//
// The VTank Monsters-tab PetDmg column (G:97) picks the essence whose pet deals
// that element; support/pets.js reads this table. ACE's DamageType names are
// normalised to the VT Element names (Electric -> Lightning, U6 §2.6).
//
// Usage (from apps/holtburger-web/):
//   node rynth/vt/tools/gen_pet_essences.cjs           check the committed JSON (exit 1 on drift)
//   node rynth/vt/tools/gen_pet_essences.cjs --write   regenerate it
//   ... [--ace <path to PetDevice.cs>]
// When the ACE source is absent the check passes with "0 source checks" (the
// committed JSON is the runtime truth; the source is only the generator input).

"use strict";

const fs = require("node:fs");
const path = require("node:path");

const HW = path.resolve(__dirname, "..", "..", "..");
const OUT = path.join(HW, "rynth", "vt", "data", "pet_essences.json");
const DEFAULT_SRC = path.resolve(HW, "..", "..", "..", "ACE", "Source", "ACE.Server", "WorldObjects", "PetDevice.cs");

const ELEMENT_OF = Object.freeze({
  Slash: "Slash",
  Pierce: "Pierce",
  Bludgeon: "Bludgeon",
  Fire: "Fire",
  Cold: "Cold",
  Acid: "Acid",
  Electric: "Lightning",
  Nether: "Nether",
});

function argValue(name) {
  const i = process.argv.indexOf(name);
  return i >= 0 && i + 1 < process.argv.length ? process.argv[i + 1] : null;
}

/** Parse the PetDeviceToPetMapping dictionary body out of PetDevice.cs. */
function parseMapping(src) {
  const start = src.indexOf("PetDeviceToPetMapping");
  if (start < 0) throw new Error("PetDeviceToPetMapping not found");
  const open = src.indexOf("{", src.indexOf("=", start));
  let depth = 0;
  let end = -1;
  for (let i = open; i < src.length; i++) {
    if (src[i] === "{") depth++;
    else if (src[i] === "}") {
      depth--;
      if (depth === 0) {
        end = i;
        break;
      }
    }
  }
  if (end < 0) throw new Error("unterminated PetDeviceToPetMapping");
  const body = src.slice(open + 1, end);
  // One row per line; commented-out rows (`//{ 0, … }`) are not part of the map.
  const row = /^\s*\{\s*(\d+)\s*,\s*new\s+Tuple<uint,\s*DamageType>\(\s*(\d+)\s*,\s*DamageType\.([A-Za-z]+)\s*\)\s*\}\s*,?[ \t]*(?:\/\/[ \t]*(.*))?$/;
  const essences = {};
  let count = 0;
  for (const line of body.split(/\r?\n/)) {
    const m = row.exec(line);
    if (!m) continue;
    const wcid = Number(m[1]);
    const petWcid = Number(m[2]);
    const damageType = ELEMENT_OF[m[3]];
    if (!damageType) throw new Error(`unknown DamageType.${m[3]} for essence ${wcid}`);
    const comment = (m[4] || "").trim();
    const lv = /\((\d+)\)\s*$/.exec(comment);
    const rec = { petWcid, damageType };
    if (lv) rec.level = Number(lv[1]);
    if (comment) rec.label = comment.replace(/\s*\(\d+\)\s*$/, "");
    if (essences[String(wcid)]) throw new Error(`duplicate essence wcid ${wcid}`);
    essences[String(wcid)] = rec;
    count++;
  }
  if (count < 100) throw new Error(`only ${count} mapping rows parsed — the source layout changed`);
  return { essences, count };
}

function build(srcPath) {
  const src = fs.readFileSync(srcPath, "utf8");
  const { essences, count } = parseMapping(src);
  const sorted = {};
  for (const k of Object.keys(essences).sort((a, b) => Number(a) - Number(b))) sorted[k] = essences[k];
  return {
    json: {
      _comment:
        "Generated by `node rynth/vt/tools/gen_pet_essences.cjs --write` from ACE ACE.Server/WorldObjects/PetDevice.cs " +
        "PetDevice.PetDeviceToPetMapping (vanilla ACE, read-only). Key = essence (PetDevice) wcid; petWcid = the summoned " +
        "pet's wcid; damageType = the pet's element (ACE DamageType, Electric -> Lightning); level/label from the source " +
        "comment. Consumer: rynth/vt/support/pets.js (Monsters-tab PetDmg column, G:97).",
      v: 1,
      count,
      essences: sorted,
    },
    count,
  };
}

function main() {
  const write = process.argv.includes("--write");
  const srcPath = argValue("--ace") || DEFAULT_SRC;
  if (!fs.existsSync(srcPath)) {
    if (write) {
      console.error(`gen_pet_essences: source not found: ${srcPath}`);
      process.exit(1);
    }
    console.log(`gen_pet_essences: ACE source absent (${srcPath}) — 0 source checks; committed JSON kept`);
    return;
  }
  const { json, count } = build(srcPath);
  const text = JSON.stringify(json, null, 1) + "\n";
  if (write) {
    fs.writeFileSync(OUT, text);
    console.log(`gen_pet_essences: wrote ${count} essences -> ${path.relative(HW, OUT)}`);
    return;
  }
  const cur = fs.existsSync(OUT) ? fs.readFileSync(OUT, "utf8") : "";
  if (cur !== text) {
    console.error(`gen_pet_essences: ${path.relative(HW, OUT)} is stale vs ${srcPath} (run with --write)`);
    process.exit(1);
  }
  console.log(`gen_pet_essences: ${count} essences up to date`);
}

if (require.main === module) main();

module.exports = { parseMapping, build, ELEMENT_OF };
